<?php
declare(strict_types=1);
namespace App\Modules\CostStructure\Validators;
use App\Core\Exceptions\ValidationException;use App\Core\Validation\Validator;use App\Modules\CostStructure\DTOs\CostCodeData;
final class CostCodeValidator{public function __construct(private readonly Validator $validator){}public function validate(array $i):CostCodeData{if(!$this->validator->validate($i,['work_section_id'=>'required','cost_code'=>'required|string|max:30','name'=>'required|string|max:255','description'=>'string|max:5000']))throw new ValidationException($this->validator->errors());$section=$this->id($i['work_section_id']??null);$unit=trim((string)($i['default_unit_id']??''))===''?null:$this->id($i['default_unit_id']);$errors=[];if($section===null)$errors['work_section_id'][]='قسم الأعمال غير صالح.';if(trim((string)($i['default_unit_id']??''))!==''&&$unit===null)$errors['default_unit_id'][]='الوحدة غير صالحة.';if($errors!==[])throw new ValidationException($errors);$description=trim((string)($i['description']??''));return new CostCodeData((int)$section,trim((string)$i['cost_code']),trim((string)$i['name']),$unit,$description===''?null:$description,max(0,(int)($i['sort_order']??0)));}private function id(mixed $v):?int{$id=filter_var($v,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);return $id===false?null:$id;}}
